/bin/zsh -lc "env GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null /opt/homebrew/bin/python3 -c 'import pathlib,json,re,hashlib; R=pathlib.Path(\".\"); O=R/\"evidence/markov-cfcbaf30\"; A={}; ax={}; audits=[]; sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest(); runs=sorted(O.glob(\"run-*.json\"));
for p in runs:
 d=json.loads(p.read_text())
 if d.get(\"returncode\")"'!=0 or d.get("mode")!="build" or sha(R/d["source"])!=d["sha256"]:continue
 m=pathlib.Path(d["source"]).stem
 if "Audit" in m:
  audits.append(str(p))
  for n,v in re.findall(r"'"\\x27MathGKM.Markov.(\\w+)\\x27 depends on axioms: \\[(["'^'"\\]]*)\\]\",d[\"stdout\"],re.S):ax[n]=[a.strip() for a in v.split(\",\") if a.strip()]
 else:A[m]={\"source\":d[\"source\"],\"sha256\":d[\"sha256\"],\"build\":str(p)}
for m,d in A.items():d[\"declarations\"]=re.findall(r\""'^theorem ('"\\w+)\",(R/d[\"source\"]).read_text(),re.M)
res=dict(modules=A,axioms=ax,audit_receipts=audits,unaudited={m:[n for n in d[\"declarations\"] if n not in ax] for m,d in A.items() if any(n not in ax for n in d[\"declarations\"])},forbidden_axioms={n:v for n,v in ax.items() if set(v)-{\"propext\",\"Classical.choice\",\"Quot.sound\"}}); (R/\"evidence/markov-13d40bd7/inherited-validation-refreshed.json\").write_text(json.dumps(res,indent=2)); print(dict(modules=len(A),axioms=len(ax),unaudited=res[\"unaudited\"],forbidden=res[\"forbidden_axioms\"]))'"

